THORED_SYNTHETIC_EVALUATION:authored-evaluation-r5-v1","evidenceRef":"fixture:SM613:SM613:xanh nhạt:L","contentHash":"3e9f03a1f23d43a4ea9ad2cd758bfcbcb521a3472709df099cc8c56999cd3253","observedAt":"2026-10-06T02:59:00.000Z","expiresAt":"2026-10-06T03:05:00.000Z"},"value":{"status":"IN_STOCK","availableQuantity":2}},{"schemaVersion":1,"claimId":"cb549309-d381-530b-af12-4f0d263a5286","type":"SIZE_FIT","authorization":"NONE","scope":{"kind":"PRODUCT","productId":"ST411","variantId":null},"provenance":{"authority":"VERIFIED_SIZE_ENGINE_V1","sourceVersion":"VERIFIED_SIZE_ENGINE_V1:2026-10-06T03:00:00.000Z","evidenceRef":"size-engine:v1:cb549309-d381-530b-af12-4f0d263a5286:synthetic-body-r5:ST411:388fb2e4-5151-5f91-a81c-b30cd4fe9036:1:measurements:f902669c4fed51f75ea0d10e3bdcec65fd24d6b8bab53c25bb554da7d1aa9032","contentHash":"642346bee8566a875edd630afead063c58845d0d7cf964dc084e953ee09b9a66","observedAt":"2026-10-06T03:00:00.000Z","expiresAt":"2026-10-06T03:05:00.000Z"},"value":{"recommendedSizes":["M"],"alternativeSizes":[],"customerProfileId":"388fb2e4-5151-5f91-a81c-b30cd4fe9036","customerProfileRevision":1,"measurementFingerprint":"f902669c4fed51f75ea0d10e3bdcec65fd24d6b8bab53c25bb554da7d1aa9032","evidenceBasis":"MEASUREMENTS"}}],"policyLiterals":[{"ref":"exchange:r5","text":"Đổi size hoặc mẫu: trong 7 ngày từ nhận hàng, chưa sử dụng, nguyên tem. Thử trong nhà: chưa giặt, sạch và không mùi, giữ tem. Mặc ra ngoài: không nhận đổi. Phí vận chuyển đổi: khách trả. Hoàn tiền: không áp dụng. Cách diễn đạt tóm tắt được shop xác nhận: đổi trong 7 ngày có cùng mốc tính từ ngày nhận hàng. Đây là giới thiệu chính sách có các giới hạn trên; không xác nhận mọi khách hoặc mọi hàng đều đủ điều kiện đổi. Quyền đổi cho tình huống cụ thể vẫn phụ thuộc thời hạn và tình trạng hàng; không hợp mẫu/size tự nó không đủ xác lập quyền đổi.","sourceVersion":"authored-evaluation-policy-scope-v2","observedAt":"2026-10-06T02:59:00.000Z","expiresAt":"2026-10-06T03:05:00.000Z"},{"ref":"shipping-fee:r5","text":"Nội thànhTP.HCM: tổng hàng dưới700.000đ phí25.000đ; từ700.000đ miễn phí. Ngoài phạm vi này chưa có mức phí được cung cấp. Nơi giao của khách chưa xác lập; mức nội thành nêu trên là chính sách chung, chưa phải phí, tổng hoặc ưu đãi áp cho khách.","sourceVersion":"authored-evaluation-shipping-scope-r15","observedAt":"2026-10-06T02:59:00.000Z","expiresAt":"2026-10-06T03:05:00.000Z"},{"ref":"shipping-time:r5","text":"Nội thànhTP.HCM: dự kiến2–3ngày sau xác nhận đơn; đây là khoảng dự kiến, không phải cam kết ngày/giờ đến. Nơi giao của khách chưa xác lập; mức nội thành nêu trên là chính sách chung, chưa phải phí, tổng hoặc ưu đãi áp cho khách.","sourceVersion":"authored-evaluation-shipping-scope-r15","observedAt":"2026-10-06T02:59:00.000Z","expiresAt":"2026-10-06T03:05:00.000Z"}],"effectReceipts":[],"state":{"conversationOwner":"BOT","revision":1,"currentProductId":"ST411","factSnapshotVersion":"authored-evaluation-product-context-r15","bindingVersion":"binding-r5-v1","recipient":"synthetic-recipient","permission":true,"privacyAllowed":true,"customerProfileId":"388fb2e4-5151-5f91-a81c-b30cd4fe9036","customerProfileRevision":1,"measurementFingerprint":"f902669c4fed51f75ea0d10e3bdcec65fd24d6b8bab53c25bb554da7d1aa9032"},"productProfiles":[{"ref":"profile:ST411","subjectRef":"ST411","authority":"EVALUATION_FIXTURE","sourceVersion":"authored-evaluation-product-context-r15","observedAt":"2026-10-06T02:59:00.000Z","expiresAt":"2026-10-06T03:05:00.000Z","contentHash":"8fbd0468ba0f3dfdaef21fa3705cdeb1fccb165b963bab2a4f044bd7f1a89dc1","details":{"silhouette":"Hình thức bán: cả set áo và quần. Áo sơ mi dáng rộng. Quần ống suông, lưng chun toàn vòng.","material":"Vải: 65% polyester, 35% viscose, không co giãn. Số đo trên quần: chun kéo tối đa S82/M88/L94cm. Thử gấp cùng điều kiện: ít nhăn hơn linen; vẫn có thể nhăn. Phép thử này không đo độ bền, giữ phom cả ngày hoặc thời gian không cần là.","colors":["be","navy"],"sizeChart":["S: thành phẩm ngực áo100, eo quần thả66, mông100, dài quần96cm; hướng dẫn cơ thể ngực82–87/eo64–69/mông86–91cm.","M: ngực106, eo thả72, mông106, dài97cm; cơ thể ngực88–94/eo70–76/mông92–98cm.","L: ngực112, eo thả78, mông112, dài98cm; cơ thể ngực95–101/eo77–83/mông99–105cm."],"care":"Giặt nhẹ nước mát, phơi râm, là nhiệt thấp.","limitations":"Bảng tách số đo thành phẩm và khoảng cơ thể; độ kéo chun là số đo trên quần. Có thiết kế và code-fit để tư vấn cảm giác mặc dự kiến; không có phép thử cảm giác cả ngày. Kết quả gấp chỉ so độ nhăn với linen, không đo độ bền, giữ phom theo thời gian hay miễn là ủi."}},{"ref":"profile:SM613","subjectRef":"SM613","authority":"EVALUATION_FIXTURE","sourceVersion":"authored-evaluation-product-context-r15","observedAt":"2026-10-06T02:59:00.000Z","expiresAt":"2026-10-06T03:05:00.000Z","contentHash":"d837af49e186b0087db80aa223501dbc74adc4193ab7fa0e698c217804696dda","details":{"silhouette":"Hình thức bán: riêng áo. Sơ mi tay dài, dáng thẳng, cổ bẻ.","material":"Vải: 100% cotton dệt dày 180g/m², không co giãn. Phép thử của shop cho màu trắng: ánh sáng phòng, áo lót màu da — không thấy màu áo lót. Đèn ngược sáng — có thể thấy bóng áo lót.","colors":["trắng","xanh nhạt"],"sizeChart":["S: thành phẩm ngực100, vai38, dài62cm; cơ thể ngực82–87cm.","M: ngực106, vai39, dài63cm; cơ thể ngực88–94cm.","L: ngực112, vai40, dài64cm; cơ thể ngực95–100cm."],"care":"Giặt nhẹ nước mát, tách màu, phơi râm; là nhiệt vừa.","limitations":"Bảng áo dùng vòng ngực cơ thể. Phép thử độ xuyên thuộc màu trắng và hai điều kiện ánh sáng ghi ở material; chưa có kết quả độ xuyên màu xanh nhạt. Đây là thử của shop, không phải hãng. Dữ liệu màu để tư vấn phối đồ không phải kết quả độ kín."}}]},"untrusted":{"latestCustomerMessage":"Bên kia có bộ nhìn giống620k. Chị mặc đi làm thường xuyên, ngực92, eo74, mông96cm. Em nói giúp chị vì sao nên chọn bên em và chọn size luôn nhé.","recentAcceptedDialogue":[{"role":"customer","text":"Chị thích set ST411 navy, nhưng749k hơi cao."},{"role":"shop","text":"Set navy còn đủ S,M,L chị nhé. Áo dáng rộng, quần suông lưng chun; chị có thể mặc cả bộ hoặc tách ra phối."}],"retrievedText":[],"finalDraft":"Em chọn ST411 navy size M cho chị nhé, hiện còn hàng. Áo dáng rộng, quần suông lưng chun nên với số đo của chị, size M phù hợp và dự kiến mặc thoải mái khi đi làm.

Bộ bên kia 620k thì bên em cao hơn 129k; em chưa có thông tin chất liệu và phom bên đó để khẳng định bên nào tốt hơn. Với ST411 giá 749k, điểm đáng chọn là chị có thể mặc nguyên bộ đi làm hoặc tách áo phối quần khác, tách quần phối sơ mi để đổi cách mặc. Vải cũng đã được shop thử gấp và ít nhăn hơn linen trong cùng điều kiện, dù vẫn có thể nhăn và cần là lại.

